MIRU_RULES.checkStandards12 = MIRU_RULES.checkStandards;
MIRU_RULES.checkStandards = function (cfg, cards, chapters, outline) { const c = Object.assign({}, cfg || {}); if (c.heat === "heat_mid") c.heat = "slow"; return MIRU_RULES.checkStandards12(c, cards, chapters, outline); };

/* ===== MIRU V2.1｜互动剧本与人物生成规则（2026-10-25）：生成器读 v21；第③步 checkV21 按 P0 / P1 / P2 分级 ===== */
var MIRU_V21="MIRU V2.1｜互动剧本与人物生成规则（生成器执行版）\n核心原则：主线快、人物深、背景厚、交流活、变化真、结局有因果；声音有个性，服装有人设，音画与行为始终属于同一个人。角色卡定义“这个人是谁、怎样表现”，剧情导演定义“事件何时发生、如何切换与裁决”，二者通过共享状态连接。\n五层：L1 世界事实（规则、历史、时间线、完整真相）/ L2 人物模型 / L3 状态与因果（关系、选择、秘密、记忆、条件、结局变量）/ L4 玩家叙事（开局、章节、分支、结局）/ L5 交互陪伴（自由聊天、日常话题、追问、特殊互动、个人事件）。L4 与 L5 共用 L3 状态，不得互相矛盾。\n冰山信息：每项重要信息记录完整事实、涉及角色、各方知情范围、玩家发现条件与渠道、发现后影响、未发现时如何推进。级别 A 主线必要（必须可得）/ B 关系增强 / C 世界深层 / D 专属秘密。“正文没写”不等于隐藏设计。秘密按 痕迹→怀疑→局部事实→真相→情绪意义 分层；区分不愿说、不能说、不知道、理解错误、玩家尚未问到。\n规模节奏：核心 10–14 章（可 8–16）；开局 30 秒吸引、3 分钟首次有效互动、10 分钟首次关系或情绪变化；每章至少一次小型情绪兑现；每 2–3 章一次大型高潮；少量关键长分支 + 高频短分支和状态差异。每章必须有可感知的推进、玩家参与、关系变化或情绪兑现、后续驱动力；压缩无关设定、重复情绪和纯过渡。\n开局：0–30 秒直接进入冲突或吸引场景（对峙、救援、意外亲密、误会、人物反差、身份异常），禁止长篇设定旁白；30 秒–3 分钟至少一位关键角色明确回应玩家，玩家能表态，不同回应即时反馈；3–10 分钟完成“初始冲突→玩家参与→人物反应→情绪或关系变化→新问题”闭环，至少一次合理反差与可深挖细节。禁止无因暧昧、虚假危机、连续介绍角色而没有建立关系。\n人物分类：P 玩家身份（只固定客观背景、起始处境、已发生事件和必要的生物性别；不预设玩家性格、价值观、喜好和私人感情）；R 可攻略角色（A–N 十四模块：A 身份基础 B 性格结构 C 人生经历 D 日常生活 E 语言风格 F 情感机制 G 核心心理 H 人物关系 I 故事知识 J 成长弧光 K 聊天知识（日常话题、私人经历、敏感主题、回避方式、事件入口）L 动态行为 M CV 声线 N 服装造型）；N 非攻略角色（关键配角写完整动机、关系、认知、必要声音与造型；普通配角简化）。核心设定形成“背景原因→人物信念→日常表现→冲突表现→变化条件”链；好感上升不改掉全部性格。\nM CV：voice_id（不得用人名临时代替）、听感年龄、音高音域明暗厚度共鸣颗粒气声鼻音沙哑、语速断句停顿重音、语言口音与切换规则、辨识点（不滥用）、社交面具与真实声线、情绪演绎表、关系阶段表（陌生/熟悉/暧昧/亲密/冲突/和解的声线与称呼）、表演禁区、选型参考只做方向沟通不模仿真实演员、TTS 配置（引擎、preset、参数、情绪标签、停顿、发音词典、版本）、质量验证。固定声纹与动态表演分离，动态变化要有触发条件和恢复规则，不由单一好感值控制。表演矩阵至少 日常 / 工作社交 / 调情 / 冲突 / 脆弱 / 和解 六类，每类写触发条件、声学变化、说话习惯、至少一句测试台词、禁止表现。CV 不得用语气提前确认未揭露的秘密；配音只消费通过知识边界裁决的台词。\nN 服装：outfit_id、审美定位及来源、色彩系统（主色/辅色/禁忌色）、外貌锚点（不可漂移）、材质版型季节、基础衣橱（日常/职业正式/居家/私下外出）、剧情服装（按故事需要）、配饰仪容、习惯动作、状态变化、记忆反馈（玩家评价被记住后是否何时回应）、美术规范（正反侧参考、色卡、材质关键词、正负提示词、版本）、授权。LOOK 变体 pristine / casual / disheveled / wet 必须有可发生的情境，不随机切换，共享外貌锚点。换装不能脱离经济、场景和心理逻辑，不为展示或付费牺牲人物逻辑。\n世界与故事圣经：时代、社会文化、地理、组织、权力利益、制度或特殊能力、现实限制；开局前历史、核心冲突成因、关键人物行动动机、误会谎言、开局局势、重大选择带来的变化、每个结局的因果。冰山事件写编号、客观事实、表象、涉及角色、动机、认知、可见痕迹、线索、可能误解、揭露条件与方式、剧情及关系影响。\n主线：三阶段 ①强吸引与快速卷入 ②关系深化与认知动摇 ③真相及选择兑现。每章记录 章节ID/标题、初始局势、核心目标与冲突、人物、事件顺序、玩家行动、分支、关系变化、情绪兑现、隐藏信息、结束状态、后续悬念；单章节拍 快速入场→冲突升级→玩家行动→人物反馈→兑现→后续驱动。对白表达意图与潜台词，不为解释设定重复陈述；台词、动作、情绪标签、声音状态可分离调用。\n互动：四类入口 交流入口 / 日常话题 / 剧情切入点 / 特殊互动。回复读取人物画像、剧情状态、认知、关系、情绪、有效记忆和上下文；信息揭露裁决 是否知道、是否愿说、是否有更高保密义务、是否破坏关键剧情；允许合理隐瞒、拒绝、误解、片面解释，但不机械拒绝。未定义的重大往事、血缘、世界规则及秘密不得自由编造；一句闲聊不能重写核心事实。\n关系与弧光：好感、信任、亲密、冲突/戒备及角色专属心理变量；重大阶段需数值与事件/行为条件共同满足；R 类写错误信念、成因、外在表现、变化事件、玩家影响、新行为、变化失败路径；反馈体现在称呼、行为、主动联系、秘密分享、冲突处理，也可映射到 CV 和服装，绝不只改数字。\n分支：S 即时差异 / M 短期分支（可合流）/ L 长期分支 / E 结局分支；优先 S、M 高频差异，L、E 放在有明确价值冲突与代价的节点；合流保留选择历史；同一真相被主动坦白、第三方转述、自行调查发现应有不同关系后果；结局由剧情、关系、关键行为、秘密及道具等多个状态联合判定，不只由最后一道选择决定。\n道具与商业化：每个重要道具有使用与未使用两条结果；免费路径不缺主线必要因果；付费优先提供额外情绪体验、个人内容、可选路径；影响重大关系与结局的必须标注并审计公平性；特殊服装和专属语音只是可选演出，不替代必要剧情解释。\n记忆与表现：剧情事实 / 玩家行为 / 关系记忆 / 交流记忆；角色只回忆亲历、获知或合理推断的事；普通聊天态度不自动变成不可撤销承诺；秘密揭露、重大争执不在模式切换时重置。表现流程：已确认状态 → 人物知识与内容裁决 → 台词/行为 → CV 情绪标签及服装状态 → 演出；配音、立绘切换不得反向写入剧情真相；玩家对穿搭的评价先形成交流记忆，再由人物意愿和事件条件决定是否真实换装。\n编号：CHAR 人物 / CH 章节 / SC 场景 / NODE 节点 / OPT 选项 / TOPIC 话题 / SECRET 秘密 / EVENT 事件 / ITEM 道具 / MEM 记忆 / END 结局 / VOICE 声音 / OUTFIT 服装 / LOOK 服装变体 / PERF 演绎状态，作品内唯一。\n工作流：故事定位 → 世界与真相 → 人物档案（含 CV、服装）→ 冰山信息 → 开局设计 → 主线结构 → 陪伴互动 → 状态与结局 → 正文与演出 → 一致性审计；先结构后正文，只交付一套内部一致的成品；音频和立绘素材没做的标“待生产”，不得伪称已有。\n验收分级：P0 禁止交付（因果矛盾、知识泄漏、状态冲突、不可达结局、资产身份严重错配）；P1 必须修正（人物及声线不一致、无效选择、服装突变、关键反馈缺失）；P2 质量优化（冗长对白、次要角色弱、话题重复、局部表演或穿搭表现不足）。\n不可违反：不以正文长度代替故事厚度、不以标签代替行为；不用冗长背景开局、不让玩家长期只能看；不割裂自由聊天与主线、不让角色知道不可能知道的事；不用无因误会、突变情感、空反转；不设没有实质反馈的选择；不通过付费剥夺必要因果；不为压缩删除关键情绪兑现、不让隐藏内容缺发现渠道；结局不与弧光和重大行为脱节；CV 音色口音不随情绪漂移、配音不泄漏未知内容；服装脸部体型仪容不随机漂移；商业化配置不覆盖底层人格与剧情事实。";
MIRU_RULES.v21 = MIRU_V21;
MIRU_RULES.version = MIRU_RULES.version + " + 规则框架 V2.1";
MIRU_RULES.checkV21 = function (cfg, cards, chapters, outline) {
  const R = { err: [], warn: [] }; const O = String(outline || ""); const T = "（规则 V2.1 ";
  const P0 = (m, s) => R.err.push("P0 " + m + T + s + "）"), P1 = (m, s) => R.err.push("P1 " + m + T + s + "）"), P2 = (m, s) => R.warn.push("P2 " + m + T + s + "）");
  const chs = (chapters || []).slice().sort((a, b) => a.n - b.n);
  if (chs.length && (chs.length < 8 || chs.length > 16)) P2("章节数 " + chs.length + "，基准 10–14（可 8–16）", "第三部分");
  const c1 = chs.find(c => c.n === 1);
  if (c1) { const md = String(c1.md || ""); const lines = md.split("\n").filter(l => l.trim() && !/^#/.test(l.trim()));
    let pre = 0; for (const l of lines) { if (/[：:]\s*[“"「]/.test(l)) break; pre += l.length; } if (pre > 400) P1("第 1 章第一句对白前有约 " + pre + " 字旁白——前 30 秒要直接进入冲突或吸引场景", "第四部分");
    const firstChoice = md.search(/#\s*CHOICE/i); if (firstChoice < 0 || firstChoice > 2500) P1("第 1 章前约 3 分钟（≈2500 字内）没有玩家第一次表态的机会", "第四部分");
    if (!/【效果】/.test(md)) P1("第 1 章没有任何带效果的选择——前 10 分钟要出现第一次关系或情绪变化", "第四部分"); }
  chs.forEach(c => { const md = String(c.md || ""); if (!/#\s*CHOICE/i.test(md)) P1("第 " + c.n + " 章没有玩家选择（无效章节）", "第七部分"); const opts = (md.match(/####\s*[A-E]\s*[｜|]/g) || []).length; if (opts && !/【效果】/.test(md)) P1("第 " + c.n + " 章的选择没有任何实际后果（无效选择）", "第十部分"); });
  if (O) {
    if (!/SECRET_|作者秘密|秘密台账/.test(O)) P1("架构没有冰山秘密台账（SECRET 编号、知情范围、发现渠道、揭露条件）", "第二/六部分");
    else if (!/\b[ABCD]\s*(类|级)|级别\s*[ABCD]|主线必要/.test(O)) P2("秘密没有标 A–D 级别（A 主线必要必须可得）", "第二部分");
    if (!/S\s*即时|M\s*短期|L\s*长期|E\s*结局|分支等级|长期分支/.test(O)) P2("没有区分 S / M / L / E 分支等级", "第十部分");
    if (!/结局/.test(O)) P0("架构没有结局及其因果", "第六/十部分"); else if (!/(关系|好感|信任).{0,30}(且|并且|同时|和).{0,30}(选择|秘密|道具|行为)|多.{0,4}状态.{0,6}判定/.test(O)) P2("结局看起来只由单一条件决定，应由剧情、关系、关键行为、秘密、道具联合判定", "第十部分");
    if (/ITEM_|道具/.test(O) && !/未使用|不使用|没有使用/.test(O)) P1("道具没有写“未使用”时的结果（免费路径不能断）", "第十一部分");
    if (!/(交流入口|日常话题|剧情切入点|特殊互动|话题库|TOPIC_)/.test(O)) P2("没有配置四类互动入口 / 话题库", "第八部分");
    if (/付费.{0,20}(真相|主线|结局)/.test(O) && !/(公平|标注|免费路径)/.test(O)) P1("付费内容影响主线 / 结局但没有标注和公平性说明", "第十一部分");
  }
  const list = (cards && cards.characters) || [];
  list.forEach(c => { const n = c.name || c.key || "?"; const R_ = c.class ? c.class === "R" : (c.tier === "lead" || c.tier === "main") && c.romanceable !== false; if (!R_) return;
    const v = c.voice || {}; if (!v.voice_id && !v.voice_asset_id) P1(n + "：没有 voice_id（不得用人名临时代替）", "5.3");
    const pm = v.performance_matrix || {}; const six = ["daily", "work_social", "flirt", "conflict", "vulnerable", "reconcile"]; const miss = six.filter(k => !pm[k] || !pm[k].test_line);
    if (miss.length) P1(n + "：CV 表演矩阵缺 " + miss.length + " 类（" + miss.join("、") + "），每类要有触发条件、声学变化和测试台词", "5.3");
    if (!v.relationship_stage || Object.keys(v.relationship_stage).length < 4) P2(n + "：缺关系阶段声线表（陌生/熟悉/暧昧/亲密/冲突/和解）", "5.3");
    const of = c.outfits || []; if (!of.length) P1(n + "：没有服装套装（OUTFIT）", "5.4");
    else { if (of.some(o => !o.outfit_id)) P1(n + "：有服装没有 outfit_id", "5.4"); if (!of.some(o => /日常|daily/i.test(JSON.stringify(o.scenes || o.name || "")))) P2(n + "：基础衣橱缺日常装", "5.4"); if (of.some(o => (o.looks || []).some(l => l && typeof l === "object" && !l.condition))) P1(n + "：服装变体（LOOK）没写触发情境，不能随机切换", "5.4"); }
    if (!c.chat_knowledge || !(c.chat_knowledge.daily_topics || []).length) P2(n + "：缺 K 聊天知识（日常话题、敏感主题、回避方式、事件入口）", "5.2 K"); });
  return R;
};
